result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/metagen/src/meta.js", "content": "import * as cheerio from 'cheerio';

const MAX_DESCRIPTION = 155;

/**
 * Escape a value for safe use inside a double-quoted HTML attribute
 * or element text content.
 */
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Truncate `text` to at most MAX_DESCRIPTION characters on a word boundary,
 * leaving no dangling space or comma (or other sentence punctuation).
 */
export function truncateDescription(text) {
  const str = String(text ?? '');
  if (str.length <= MAX_DESCRIPTION) return str;

  const sliced = str.slice(0, MAX_DESCRIPTION);
  const lastSpace = sliced.lastIndexOf(' ');
  let out = lastSpace > 0 ? sliced.slice(0, lastSpace) : sliced;
  // Strip any dangling whitespace / separator punctuation left at the edge.
  out = out.replace(/[\s,;:!\u2013\u2014-]+$/, '');
  return out;
}

/**
 * Render the social meta-tag block for a page.
 *
 * Produces:
 *  - <title> and <meta name="description"> (description truncated at 155 chars)
 *  - <link rel="canonical"> when `url` is given
 *  - Open Graph pairs: og:title, og:description, og:url, og:image,
 *    og:site_name, og:type (default "website")
 *  - Twitter card: twitter:card is "summary_large_image" when an image is
 *    present, otherwise "summary"; plus twitter:title/description/image
 */
export function renderMeta({
  title,
  description,
  url,
  image,
  siteName,
  type,
} = {}) {
  const desc = truncateDescription(description);
  const cardType = image ? 'summary_large_image' : 'summary';
  const ogType = type || 'website';

  const lines = [];

  if (title != null) lines.push(`  <title>${escapeHtml(title)}</title>`);
  if (description != null) {
    lines.push(`  <meta name="description" content="${escapeHtml(desc)}" />`);
  }
  if (url != null) {
    lines.push(`  <link rel="canonical" href="${escapeHtml(url)}" />`);
  }

  const og = [
    ['og:title', title],
    ['og:description', desc],
    ['og:url', url],
    ['og:image', image],
    ['og:site_name', siteName],
    ['og:type', ogType],
  ];
  for (const [property, value] of og) {
    if (value == null) continue;
    lines.push(
      `  <meta property="${property}" content="${escapeHtml(value)}" />`
    );
  }

  const twitter = [
    ['twitter:card', cardType],
    ['twitter:title', title],
    ['twitter:description', desc],
    ['twitter:image', image],
  ];
  for (const [name, value] of twitter) {
    if (value == null) continue;
    lines.push(
      `  <meta name="${name}" content="${escapeHtml(value)}" />`
    );
  }

  return `<meta charset="utf-8" />\n${lines.join('\n')}`;
}

/**
 * Parse an HTML document back into the meta object it describes.
 * Inverse of renderMeta for canonical inputs.
 */
export function parseMeta(html) {
  const $ = cheerio.load(html);
  const meta = (selector) => $(selector).attr('content');

  const result = {};

  const title = $('title').first().text();
  if (title) result.title = title;

  const description = $('meta[name="description"]').attr('content');
  if (description != null) result.description = description;

  const url = $('link[rel="canonical"]').attr('href');
  if (url != null) result.url = url;

  const image = $('meta[property="og:image"]').attr('content');
  if (image != null) result.image = image;

  const siteName = $('meta[property="og:site_name"]').attr('content');
  if (siteName != null) result.siteName = siteName;

  const type = $('meta[property="og:type"]').attr('content');
  if (type != null) result.type = type;

  // Prefer og:* values where present; fall back to plain tags already set.
  const ogTitle = $('meta[property="og:title"]').attr('content');
  if (ogTitle != null) result.title = ogTitle;

  const ogDesc =
    $('meta[property="og:description"]').attr('content');
  if (ogDesc != null && result.description === undefined) {
    result.description = ogDesc;
  }

  return result;
}
"})
