result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/metagen/test/meta.test.js", "content": "import { describe, it, expect } from 'vitest';
import { renderMeta, parseMeta, truncateDescription } from '../src/meta.js';

describe('renderMeta / parseMeta round-trip', () => {
  it('round-trips a fully populated object', () => {
    const input = {
      title: 'My Page Title',
      description: 'A concise description of the page.',
      url: 'https://example.com/page',
      image: 'https://example.com/cover.jpg',
      siteName: 'Example Site',
      type: 'article',
    };
    const html = renderMeta(input);
    expect(parseMeta(html)).toEqual(input);
  });

  it('round-trips a minimal object without optional fields', () => {
    const input = {
      title: 'Bare Page',
      description: 'Short text.',
      url: 'https://example.com/',
    };
    expect(parseMeta(renderMeta(input))).toEqual(input);
  });
});

describe('description truncation', () => {
  it('truncates a 200-char description to <=155 chars on a word boundary', () => {
    const words =
      'alpha bravo charlie delta echo foxtrot golf hotel india juliet kilo lima mike november oscar papa quebec romeo sierra tango uniform victor whiskey xray yankee zulu one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty';
    // Build exactly 200 characters by trimming whole words.
    let desc = '';
    for (const w of words.split(' ')) {
      if ((desc + ' ' + w).trim().length > 200) break;
      desc = (desc + ' ' + w).trim();
    }
    expect(desc.length).toBe(200);

    const truncated = truncateDescription(desc);
    expect(truncated.length).toBeLessThanOrEqual(155);
    expect(truncated.length).toBeGreaterThan(100); // actually truncated
    expect(truncated).not.toBe(desc);

    // No dangling comma or trailing space.
    expect(truncated.endsWith(',')).toBe(false);
    expect(truncated.endsWith(' ')).toBe(false);

    // Word boundary: original continues with whitespace after the cut.
    const nextChar = desc[truncated.length];
    expect(nextChar).toBe(' ');
    expect(desc.startsWith(truncated)).toBe(true);
  });

  it('leaves short descriptions untouched and renders them verbatim', () => {
    expect(truncateDescription('short')).toBe('short');
    const html = renderMeta({ title: 't', description: 'short' });
    expect(html).toContain('content="short"');
  });

  it('never ends with a comma even when the word boundary follows one', () => {
    const desc = `${'x'.repeat(150)}, trailing words continue here beyond limit`;
    const out = truncateDescription(desc);
    expect(out.endsWith(',')).toBe(false);
    expect(out.endsWith(' ')).toBe(false);
  });

  it('renders the truncated description in both og and description tags', () => {
    const long = 'word '.repeat(50).trim(); // 249 chars
    const html = renderMeta({ title: 't', description: long });
    const parsed = parseMeta(html);
    expect(parsed.description.length).toBeLessThanOrEqual(155);
    expect(html.match(new RegExp(parsed.description, 'g'))?.length).toBe(3);
  });
});

describe('escaping', () => {
  it('escapes quotes and specials in the title', () => {
    const html = renderMeta({
      title: 'The "Best" <Page> & Friends\' Guide',
      description: 'desc',
      url: 'https://example.com/?a=1&b=2',
    });
    expect(html).toContain(
      '<title>The &quot;Best&quot; &lt;Page&gt; &amp; Friends&#39; Guide</title>'
    );
    expect(html).toContain('content="The &quot;Best&quot;');
    // Canonical href keeps & escaped too.
    expect(html).toContain('href="https://example.com/?a=1&amp;b=2"');

    // And it inverts cleanly back through cheerio.
    const parsed = parseMeta(html);
    expect(parsed.title).toBe('The "Best" <Page> & Friends\' Guide');
    expect(parsed.url).toBe('https://example.com/?a=1&b=2');
  });
});

describe('twitter card type switching', () => {
  it('uses summary_large_image when an image is present', () => {
    const html = renderMeta({
      title: 't',
      description: 'd',
      url: 'https://example.com',
      image: 'https://example.com/img.png',
    });
    expect(html).toContain('name="twitter:card" content="summary_large_image"');
    expect(html).toContain('property="og:image" content="https://example.com/img.png"');
    expect(html).toContain('name="twitter:image" content="https://example.com/img.png"');
  });

  it('falls back to summary when no image is given', () => {
    const html = renderMeta({
      title: 't',
      description: 'd',
      url: 'https://example.com',
    });
    expect(html).toContain('name="twitter:card" content="summary"');
    expect(html).not.toContain('summary_large_image');
    expect(html).not.toContain('og:image');
    expect(html).not.toContain('twitter:image');
  });

  it('emits canonical link, og defaults, and plain title/meta description', () => {
    const html = renderMeta({
      title: 'Home',
      description: 'Welcome.',
      url: 'https://example.com/',
      siteName: 'Example',
    });
    expect(html).toContain('<title>Home</title>');
    expect(html).toContain('<meta name="description" content="Welcome." />');
    expect(html).toContain('<link rel="canonical" href="https://example.com/" />');
    expect(html).toContain('property="og:type" content="website"');
    expect(html).toContain('property="og:site_name" content="Example"');
  });
});
"})
